from build import h4, arrow, box, c, fig, flow, note, p, path, rif, seq, steps, table, text, ul, warn, zone

S1 = p("Each window of a phone app is a video session. On the phone a session is a virtual display, an H.264 hardware encoder fed by it, and the app launched on that display. "
       "The code is in " + c("telefono/video") + ": " + c("Video") + " (commands and the channel), " + c("Sessione") + " (one session), " + c("Codificatore") + " (the encoder), " + c("ControlloSchermi") + " (protected windows) and " + c("NascosteVideo") + " (hidden APIs).", lead=True) + \
    table(["Class", "Role"], [
        [c("Video"), "registers commands " + c("0x40") + "-" + c("0x4f") + ", the channel " + c("video") + " and a close action; keeps the map id → session"],
        [c("Sessione"), "virtual display, encoder, app launch, guard thread, pause, resize, close"],
        [c("Codificatore"), "one MediaCodec H.264 encoder with its input surface and the thread that reads packets"],
        [c("Inoltro"), "turns encoder output into protocol packets and keeps the configuration aside until a channel exists"],
        [c("ControlloSchermi"), "one thread for all sessions: a window dump every second to detect protected screens"],
        [c("AnalisiFinestre"), "pure parser of that dump"],
        [c("LiberaTask"), "removes the tasks of a display and waits for it to empty"],
        [c("Specchio"), "real screen size, to bring the input of a mirror session to the real display"],
        [c("Input"), c("Iniettore") + ", " + c("Gesti") + ", " + c("Pizzico") + ": input injection (chapter 10)"],
    ], "«TAB» — Classes of " + c("telefono/video")) + \
    p("<b>Checks on " + c("VIDEO_APRI") + ".</b> Width and height must be multiples of 8 between 64 and 2560; dpi between 40 and 1000; bit rate between 100000 and 200000000; the package, if present, must match " + c("[A-Za-z0-9_.]{1,255}") + "; the id must be unused in this connection. An fps outside 1..120 becomes 60. Anything else answers " + c("ERRORE") + ".")

S2 = p("The session is created in " + c("Sessione.apri") + " in this order: resolve the app, create the encoder, create the virtual display on the encoder's surface, launch the app. A failure at any step releases what was already made.", lead=True) + \
    steps([
        "<b>Resolve</b> the launcher activity with the " + c("PackageManager") + " (" + c("ACTION_MAIN") + " + " + c("CATEGORY_LAUNCHER") + ", restricted to the package; no implicit resolution). The class name must match a safe pattern and the package must be the one asked.",
        "<b>Encoder.</b> " + c("Codificatore.crea") + " tries, in order: every hardware H.264 encoder with SPS/PPS prepended to key frames, then every hardware encoder without, then Android's default encoder. The last error goes in the message. Format: surface input, the requested bit rate and frame rate, key frame interval 10 s, priority 0 (real time), " + c("KEY_REPEAT_PREVIOUS_FRAME_AFTER") + " 100000 µs (without it many encoders emit nothing on a still screen).",
        "<b>Virtual display.</b> " + c("DisplayManager.createVirtualDisplay") + " is tried with sets of flags from the richest to the simplest and the first accepted wins. For an app, four sets: public + own-content-only + touch + destroy-with-content + trusted + own group + always unlocked; the same without always-unlocked; public + own-content-only + touch + destroy-with-content; and the last without public. For the mirror: mirror + public, mirror, mirror + own-content-only. The flags used are logged.",
        "<b>Launch</b> with " + c("am start-activity --display <id> -n <component> -f 0x18000000") + " (new task + clear task), 10 s limit; output containing " + c("Error") + " or “Activity not started” fails the open.",
        "<b>Guard.</b> A thread checks every second that the app is still on the display; after it has been seen and then found missing twice in a row it sends the event " + c("VIDEO_EVENTO 1") + " (the app closed by itself; the session stays to be closed by the PC).",
    ]) + \
    table(["Event " + c("che cosa"), "Meaning", "a, b"], [
        [c("1"), "the app closed itself", "0, 0"],
        [c("2"), "protected screen on or off (" + c("FLAG_SECURE") + ")", "a = 1 or 0"],
        [c("3"), "the size changed on its own: defined by the protocol, never sent by this version of the phone code", "a × b"],
        [c("4"), "encoder error: the session is dead", "0, 0"],
    ], "«TAB» — " + c("VIDEO_EVENTO") + " kinds") + \
    p("The protected-screen state is computed once per second for all sessions at once by one " + c("dumpsys window") + " analysis (each dump holds the WindowManager lock, so there must be only one); the event goes out only when the state changes.")

SEQ = seq([("window", "shell stream", "navy"), ("PC", "componente", "blue"), ("phone", "Sessione", "dark")], [
    (0, 1, "sv_flusso_apri: 8 Mbit/s, 60 fps"),
    (1, 2, "VIDEO_APRI id, size, dpi, package"),
    (2, 1, "OK: session exists", True),
    (1, 2, "open channel video:<id>"),
    (2, 1, "CONFIGURAZIONE (SPS+PPS)", True),
    (2, 1, "key frame, then FOTOGRAMMI", True),
    (1, 0, "decoded frames", True),
    ("sep", "pause, resize, key frame requests, events"),
    (0, 1, "close"),
    (1, 2, "VIDEO_CHIUDI id, remove_task"),
], "«FIG» — The life of a video session", width=900)

S3 = p("A session starts on the shell side as a stream, " + c("SvFlusso") + " in " + c("src/shell/ossatura/sv_flussi.c") + ". It holds the " + c("PhVideoFlusso") + " of the component, the decoder and the capture state. Opening, pause, resize and close run in order on the " + c("p_flussi") + " pool; input on " + c("p_input") + "; the reading thread is the one that calls " + c("sv_flusso_leggi") + ".", lead=True) + SEQ + \
    ul([
        "<b>Request.</b> " + c("VIDEO_BIT_AL_SECONDO") + " is 8000000 and " + c("VIDEO_FPS") + " is 60. The size and density come from the window; with a density of 0 the session's own density is used, or 420 if unknown. For the mirror the size is the real screen's, scaled so that no side exceeds 1920 pixels, with sides rounded down to a multiple of 8 and at least 64 (" + c("ph_ossatura_misura_specchio") + ").",
        "<b>Component.</b> " + c("ph_video_apri") + " assigns the id (an increasing counter, never reused in the connection), sends " + c("VIDEO_APRI") + ", and on " + c("OK") + " opens the channel " + c("video:<id>") + ". If anything fails after the phone created the session, " + c("VIDEO_CHIUDI") + " is sent (2000 ms) so that no virtual display is left on. The encoder starts producing when the channel opens; before that its packets are discarded and the configuration is kept aside.",
        "<b>Open job.</b> It makes up to 3 rounds, repeated only when the session vanishes and a new one appears meanwhile; with no session the stream goes to " + c("PERSO") + " and waits.",
        "<b>Rule of use.</b> Whoever calls " + c("ph_video_*") + " on a stream holds one use of the stream and of the session; whoever replaces or closes it removes the pointer first and waits for the uses to reach zero, so no call starts after " + c("ph_video_chiudi") + " and no read runs while the stream closes.",
    ]) + \
    table(["Stream state", "Entered when", "Leaves when"], [
        [c("PH_FL_APRENDO"), "session created or connection back", "open succeeded (" + c("ATTIVO") + "), no session (" + c("PERSO") + "), refused (" + c("MORTO") + ")"],
        [c("PH_FL_ATTIVO"), "open succeeded; notice " + c("APERTO") + " the first time, " + c("RIPRESO") + " later", "session lost (" + c("PERSO") + "), encoder error (" + c("MORTO") + ")"],
        [c("PH_FL_PERSO"), "the link's session was lost", "a new session exists: reopen by itself"],
        [c("PH_FL_MORTO"), "the phone refused to open, or the encoder died (event 4)", "never: it does not restart"],
    ], "«TAB» — Stream states (" + c("ph_fl_passo") + ", " + c("src/shell/ossatura/logica.c") + ")") + \
    p("On a drop every stream becomes " + c("PERSO") + ", its pinch and touch are cancelled, and a running recording is stopped with “connection lost”. On the new session " + c("sv_flussi_sessione_nuova") + " reopens every stream; the pause the shell wanted and any resize asked while the stream was absent are reapplied.")

S4 = p("Pause turns a minimised window into a stream that costs nothing. The phone detaches the encoder surface from the virtual display (" + c("VirtualDisplay.setSurface(null)") + "), so the display, the app and the encoder stay alive but no frames are produced. Measured on the test phone: resume in 0.12–0.17 s, with the phone's compositor idle during the pause and the app still alive.", lead=True) + \
    ul([
        c("VIDEO_PAUSA") + ": already paused is " + c("OK") + " with no effect; resize and key-frame requests in pause are " + c("ERRORE") + "; input does not error but has no effect (measured: with a detached surface Android does not deliver it to the app), so the PC sends none to a paused session and, before pausing, closes every touch and pinch in progress (up or cancel). Open gestures are also closed on the phone before the surface is detached, since afterwards the cancel would be lost.",
        c("VIDEO_RIPRENDI") + ": re-attaches the surface and asks for a key frame; if none arrives within about 250 ms (a still app: 12 checks of 20 ms) a redraw is forced by detaching and attaching the surface again. The first packet written after the " + c("OK") + " is a key frame, preceded by a configuration if needed. Packets written before the pause and not yet read may still arrive after the resume.",
        c("VIDEO_RIDIMENSIONA") + ": the phone creates a new encoder, resizes the display and sets the new surface, then swaps; from then no packet with the old size is written (the filter drops packets of an encoder that is no longer the current one). The first packet with the new size is a configuration. To resize a paused stream the PC resumes it first.",
        "<b>Mirror.</b> The shell never resizes the mirror: the request is ignored for sessions with an empty package. Resize requests received while paused or while the stream is absent are remembered (size and density) and applied by the resume or the reopen.",
        "<b>Density.</b> The density is part of the resize request, so a window can change the app's layout class without restarting it: this is the protocol side of the density rule described in chapter 12.",
        "<b>Barrier.</b> Pause and resize run on the streams pool and first wait (bounded) for the inputs queued before them to have been sent, so a touch is never overtaken by a pause or a resize.",
    ])

S5 = p("The channel " + c("video:<id>") + " carries phone-to-PC packets only. The PC never writes on it; if it closes it, the encoder stops (the session lives until " + c("VIDEO_CHIUDI") + "). A second channel for the same session closes the first (shutdown of output and input).", lead=True) + \
    table(["Field", "Size", "Notes"], [
        ["kind", "1 byte", "1 = CONFIGURAZIONE (SPS+PPS), 2 = FOTOGRAMMA; any other value breaks the stream"],
        ["flags", "1 byte", "bit 0 = key frame"],
        ["width", "2 bytes", "size of the video the packet belongs to"],
        ["height", "2 bytes", ""],
        ["time", "8 bytes", "microseconds, phone monotonic clock (" + c("presentationTimeUs") + ")"],
        ["length", "4 bytes", "at most 8 MiB (" + c("PH_VIDEO_MAX_PACCHETTO") + ")"],
        ["data", "length", "H.264, Annex B (start codes " + c("00 00 00 01") + ")"],
    ], "«TAB» — Video packet (18-byte header)") + \
    p("After the channel is opened the first packet is a configuration and the second a key frame. " + c("ph_video_leggi(stream, packet, timeout, error)") + " returns 1 for a packet, 0 for end of stream, " + c("PH_CANALE_ERRORE") + " or " + c("PH_CANALE_TEMPO") + ". Reads are in 50 ms slices and are resumable (a slice that expires loses nothing). The data buffer grows in pieces of 256 KiB, so a false length does not allocate everything at once; a half packet at the end is a broken stream. The data pointer is valid until the next read.")

S6 = p("Decoding is " + c("src/video/decodifica.c") + ", on FFmpeg's " + c("libavcodec") + ". The via is chosen when the decoder is created (" + c("ph_decodifica_crea") + ").", lead=True) + \
    table(["Via", "When", "Notes"], [
        [c("PH_VIA_VAAPI"), "automatic, first choice", "FFmpeg VA-API hardware device; hands the frame to the shell without copies (DMA-BUF)"],
        [c("PH_VIA_VULKAN"), "automatic, only if VA-API is missing or fails and any non-CPU Vulkan device offers " + c("VK_KHR_video_decode_h264") + " as shipped", "detected without environment variables: a function the driver keeps off does not count; CPU-type Vulkan devices are ignored; the frame is copied to memory (" + c("PH_ESPORTA_RIPIEGO") + ")"],
        [c("PH_VIA_SOFTWARE"), "last resort, or when GTK refuses the DMA-BUF", "slice threads, thread count automatic"],
    ], "«TAB» — Decoding vias (automatic order: VA-API, then Vulkan Video if the driver offers it, then software; the order is a pure function, " + c("ph_decodifica_ordine_automatico") + ", proved without a graphics card)") + \
    p("The decoder is created with " + c("AV_CODEC_FLAG_LOW_DELAY") + " and " + c("AV_CODEC_FLAG2_FAST") + " (no frame held back for reordering). For the hardware vias " + c("extra_hw_frames") + " is 6: the shell keeps some frames alive beyond the decoder's life (the one shown, the one waiting, one being delivered), and without extra surfaces the GPU's fixed pool would run out and decoding would stop. An explicit via fails if it is not available, with no silent fallback (this is for measuring); " + c("get_format") + " records when FFmpeg dropped to software (at the first packet, or at the first packet after a new configuration, for example a resize), and " + c("ph_decodifica_dai") + " then returns an error on any hardware via, the automatic one included (the check is on the via, not on whether it was explicit); the shell reacts by recreating the decoder as software, once (" + rif("When hardware decoding is not available") + ").") + \
    p("<b>Feeding.</b> A configuration packet is kept and prepended to the next frame (a configuration alone is not a frame). Packets are sent with the phone's time as pts and dts. A damaged packet is not fatal: the call fails and decoding continues from the next key frame; the reader then asks for a key frame, at most every 500 ms, because the picture stays broken until the next one (up to 10 s at the encoder's interval). The last configuration (at most 64 KiB) is stored and given to every new decoder, since an encoder that does not prepend headers would leave a new decoder without them.") + \
    p("<b>To the shell without copies.</b> " + c("ph_esporta") + " (" + c("src/video/esporta.c") + ") turns the " + c("AVFrame") + " into a " + c("PhFotogramma") + ", described in " + c("src/comune/fotogramma.h") + " without FFmpeg or GTK types. The frame belongs to the receiver, which must call " + c("ph_fotogramma_rilascia") + " exactly once, from any thread, when the picture is not needed (typically in the release function of the " + c("GdkTexture") + "); until then file descriptors and data are valid.") + \
    table(["Via", "Form", "What happens"], [
        [c("PH_ESPORTA_DMABUF"), c("PH_FOTO_DMABUF"), "VA-API frame mapped to DMA-BUF: fourcc and modifier from the DRM descriptor, planes, offsets and strides; GTK shows it as a texture without any copy"],
        [c("PH_ESPORTA_MEMORIA"), c("PH_FOTO_MEMORIA"), "frame already in memory (BGRA, RGBA, RGB24 with positive stride: not copied) or the needed YUV to RGB conversion only; format " + c("B8G8R8A8_PREMOLT") + " normally"],
        [c("PH_ESPORTA_RIPIEGO"), c("PH_FOTO_MEMORIA"), "a GPU frame that could not be mapped (Vulkan, or VA-API refused) was copied to memory; the shell writes it in the decision log once per stream"],
    ], "«TAB» — Export forms") + \
    p("Colours: BT.709 or BT.601 according to what the frame declares (undeclared: BT.709 from 720 rows up, BT.601 below), limited range unless declared; full range maps to the " + c("PIENO") + " variants; other matrices leave the choice to GTK. An offset or stride above 32 bits is an error. In the shell, " + c("sv_flusso_memoria") + " can force the software decoder when GTK refuses the DMA-BUF, which is logged (" + c("flusso in memoria invece che DMA-BUF") + ") and asks for a key frame.") + \
    warn("Direct hand-off of the video to the screen (offload) and rounded window corners are open points. Which via a given machine really uses is visible only in the decision log and was measured on one machine only.")

S7 = p("Screenshots and recordings use the decoded frames and the received packets, in " + c("src/video/cattura_png.c") + ", " + c("src/video/cattura_mp4.c") + " and " + c("src/video/cattura_nome.c") + "; the header " + c("src/video/cattura.h") + " exposes no FFmpeg type.", lead=True) + \
    p("<b>Screenshot.</b> The reader thread serves pending screenshots before " + c("ph_esporta") + " consumes the frame (same thread as the decoder: capture reads, never modifies). " + c("sv_flusso_screenshot") + " queues the request, gives it 2 s, and asks for a key frame because a still screen sends nothing. GPU frames are brought to memory with " + c("av_hwframe_transfer_data") + ", then libswscale converts any YUV 8 or 10 bit format (width and height 1 to 16384). Two destinations: a PNG file (" + c("ph_cattura_screenshot") + ") and a PNG in memory for the clipboard (" + c("ph_cattura_png_memoria") + "). No file is ever overwritten: creation is atomic with " + c("O_EXCL") + " and a taken name becomes " + c(" (2)") + ", " + c(" (3)") + " up to 999; a partial file is deleted on error.") + \
    p("<b>Names.</b> " + c("<app>") + " + date + time + extension, as " + c("<app> YYYY-MM-DD HH.MM.SS.png") + " (local time). The app part removes " + c("/ \\ : * ? \" < > |") + " and control characters (replaced by " + c("_") + "), is cut to 80 bytes without splitting a UTF-8 character, loses spaces and dots at its ends, and if nothing is left it is " + c("YASDE") + ".") + \
    p("<b>Recording.</b> The H.264 is written as received, with no re-encoding, into a fragmented MP4 (" + c("empty_moov") + ", " + c("default_base_moof") + ", " + c("frag_custom") + "): the writer closes a fragment at every key frame or about every second. Why: the file is playable even if the process dies (at most the last second is lost); a classic MP4 without the final " + c("moov") + " is unreadable. SPS and PPS go in the track description; the samples lose them, and start codes become lengths. The file is opened with " + c("O_EXCL") + ".") + \
    table(["Rule", "Detail"], [
        ["Start", "nothing is written until the first key frame (an IDR NAL with a configuration already received or in the same packet); earlier packets are dropped"],
        ["Size change", "after the first key frame the size must stay the same; a change is an error and the recording is finished by the caller"],
        ["Configuration change", "an SPS/PPS different from the one in use is an error and the frame does not enter"],
        ["Time", "the first key frame is time 0; a time not greater than the previous one is corrected (the previous frame keeps its duration); a forward jump is taken as true up to 30 minutes; the counters " + c("tempi_corretti") + " count them"],
        ["Write error", "the file is brought back to the last good point and closed; later calls return -1; the file stays playable"],
        ["Audio track", "supported by the library (Opus, 48 kHz stereo, pre-skip 312 samples) but not used: the shell opens recordings with no audio, so YASDE recordings are video only"],
    ], "«TAB» — Recording rules") + \
    p("In the shell every packet, configurations included, goes to the recording before decoding. If the writer fails the recording is stopped with a message; a drop of the connection stops it too.")

CHAIN = flow([
    ("Phone encoder", "MediaCodec H.264", "dark"),
    ("ADB channel", "Annex B packets", "blue"),
    ("FFmpeg decode", "VA-API, Vulkan, CPU", "blue"),
    ("ph_esporta", "PhFotogramma", "light"),
    ("GTK texture", "DMA-BUF or memory", "light"),
    ("GTK renderer", "chosen by GTK", "navy"),
], "«FIG» — The video chain, stage by stage", width=900)

S8 = p("This section follows one video frame from the phone's encoder to the screen and says, at every stage, who does the work (GPU or CPU) and where the data is copied. It comes from the sources; what was measured, and where, is in " + rif("Requirements and limits of hardware acceleration") + ".", lead=True) + CHAIN + \
    table(["Stage", "Code", "Who works", "What is copied"], [
        ["1. Encode", c("telefono/video/it/yasde/Codificatore.java"), "the phone's H.264 encoder, hardware if one is found", "the virtual display renders into the encoder's input surface: no copy made by YASDE code"],
        ["2. Transport", c("src/componente/video.c") + ", " + c("src/adb"), "CPU (TLS, ADB)", "each packet is read into the stream buffer (up to 8 MiB, grown in 256 KiB pieces); the decoder receives a copy of it with the stored configuration in front"],
        ["3. Decode", c("src/video/decodifica.c"), "GPU with VA-API or Vulkan; CPU with the software via", "hardware: nothing, the picture stays in GPU memory (" + c("AV_PIX_FMT_VAAPI") + " or " + c("AV_PIX_FMT_VULKAN") + "); software: the picture is written in system memory"],
        ["4. Export", c("src/video/esporta.c"), "see the table of paths below", "DMA-BUF: nothing; memory form: for a GPU frame a GPU-to-CPU download, then a CPU colour conversion into a new buffer"],
        ["5. Texture", c("src/shell/superficie/superficie.c"), "GTK, on the GTK thread", "DMA-BUF: the file descriptors are handed to GTK; memory: the buffer is wrapped in a " + c("GBytes") + " without a copy, and GTK uploads it to the GPU by itself"],
        ["6. Draw", c("GtkGraphicsOffload") + " and the renderer GTK has chosen", "GPU, with the GL or Vulkan renderer GTK chooses", "what GTK does internally with a DMA-BUF (colour conversion, a direct hand-off to the screen) is up to GTK and not controlled by YASDE (see below)"],
    ], "«TAB» — The stages of the chain") + \
    p("<b>1. Encoding on the phone.</b> " + c("Codificatore.crea") + " lists the encoders of " + c("MediaCodecList(REGULAR_CODECS)") + " that are encoders, are not aliases, report " + c("isHardwareAccelerated()") + " and not " + c("isSoftwareOnly()") + ", and support " + c("video/avc") + ", and tries them in the list's order: first each with " + c("prepend-sps-pps-to-idr-frames") + " set to 1, then each without it, and last Android's default encoder for the type (" + c("createEncoderByType") + "), which the code does not check to be hardware: it may be a software encoder. The format asks for surface input, the bit rate and frame rate of the request (the shell asks for 8000000 and 60), a key frame every 10 s, priority 0 and repeat-previous-frame after 100000 µs. Profile, level and bit-rate mode are not set: the encoder's own defaults apply. If no encoder can be configured the open fails with " + c("codificatore H.264 non configurabile") + " and the last error, the phone answers " + c("ERRORE") + " to " + c("VIDEO_APRI") + ", and the stream goes to " + c("PH_FL_MORTO") + " with the notice “This app's video has stopped”. The name of the chosen encoder is printed only by the test class " + c("ProvaVideo") + ": in a normal run it is not logged, and the service's log lines are read by the PC and thrown away.") + \
    p("<b>3. Decoding.</b> " + c("prova_via") + " (" + c("src/video/decodifica.c") + ") uses FFmpeg's " + c("h264") + " decoder with " + c("AV_CODEC_FLAG_LOW_DELAY") + " and " + c("AV_CODEC_FLAG2_FAST") + ". For a hardware via it opens the device with " + c("av_hwdevice_ctx_create(type, NULL, NULL, 0)") + " (type " + c("AV_HWDEVICE_TYPE_VAAPI") + " or " + c("AV_HWDEVICE_TYPE_VULKAN") + ": the code names no device, FFmpeg picks the default one), gives it to the codec context as " + c("hw_device_ctx") + ", installs " + c("get_format") + " that accepts only the via's own pixel format (" + c("AV_PIX_FMT_VAAPI") + " or " + c("AV_PIX_FMT_VULKAN") + "), and sets " + c("extra_hw_frames") + " to 6 (reason in " + rif("Video: receiving and decoding") + "). The hardware decoders are the FFmpeg hwaccels " + c("h264_vaapi") + " and " + c("h264_vulkan") + " compiled into the packaged FFmpeg (" + c("pacchetto/dentro.sh") + "). The software via uses slice threading with an automatic thread count. A configuration packet is kept and put in front of the next frame.") + \
    p("<b>4. Export.</b> " + c("ph_esporta") + " takes the " + c("AVFrame") + " (it becomes the function's in every case) and returns one of three forms. Their conditions, in the order the code tests them:") + \
    table(["Condition", "Form", "Steps", "Copies per frame"], [
        ["the frame is not in GPU memory (no " + c("hw_frames_ctx") + ")", c("PH_ESPORTA_MEMORIA"), "BGRA, RGBA or RGB24 with a positive stride are wrapped as they are; any other format (the normal case, YUV from the software decoder) is converted by libswscale (" + c("SWS_BICUBIC | SWS_ACCURATE_RND") + ") into a new BGRA buffer, with the matrix and range of the frame", "0 if already RGB, otherwise 1 conversion on the CPU"],
        ["VA-API frame and " + c("av_hwframe_map") + " to " + c("AV_PIX_FMT_DRM_PRIME") + " succeeds", c("PH_ESPORTA_DMABUF"), "the DRM descriptor gives the file descriptors, offsets, strides, modifier and fourcc; the mapped frame keeps the picture alive until GTK releases the texture", "0"],
        ["a GPU frame that is not VA-API (Vulkan), or whose mapping was refused", c("PH_ESPORTA_RIPIEGO"), c("av_hwframe_transfer_data") + " brings the picture to system memory, then the same conversion as above", "1 download GPU to CPU plus 1 CPU conversion"],
    ], "«TAB» — The forms of " + c("ph_esporta")) + \
    p("In " + c("PH_ESPORTA_DMABUF") + " the fourcc is the layer's format when there is one layer, or NV12 or P010 (from the frame's software format) for multi-layer descriptors; at most 4 planes; all planes must have the same modifier or the export fails; sizes up to 16384. In the " + c("PH_ESPORTA_RIPIEGO") + " case the shell writes one decision line per stream (" + rif("Checking which path is in use") + ").") + \
    p("<b>5. The texture</b> (" + c("texture_da") + ", " + rif("The video surface") + "). For a memory frame: " + c("gdk_memory_texture_new") + " with the format " + c("GDK_MEMORY_B8G8R8A8_PREMULTIPLIED") + ", " + c("R8G8B8A8") + " or " + c("R8G8B8") + ". For a DMA-BUF: " + c("GdkDmabufTextureBuilder") + " with the fourcc, modifier, planes, offsets and strides of the frame. Before the first DMA-BUF the surface asks GTK for its list of importable formats (" + c("gdk_display_get_dmabuf_formats") + "); if the pair fourcc and modifier is not in it, it logs a line and tries anyway. If the builder returns no texture (its error is discarded) the frame is dropped and counted as a refusal, which has consequences described in " + rif("When hardware decoding is not available") + ". For a DMA-BUF texture only (memory textures are already BGRA, with the matrix applied by libswscale in the export), the colour state is given only if the program was compiled against GTK 4.16 or newer: BT.709 or BT.601 (CICP primaries, transfer and matrix 1/1/1 or 6/6/6) with narrow or full range, from what the frame declares or the height rule; for any other matrix, or if GTK does not build the colour state (one log line), GTK decides.") + \
    p("<b>6. Drawing.</b> The picture is a " + c("GtkPicture") + "-like widget (" + c("PhImmagine") + ") inside a " + c("GtkGraphicsOffload") + " with offload enabled (and, from GTK 4.16, a black background). The widget appends a plain texture node because GTK 4.18 does not offload a scaled-texture node. The program never sets the renderer: GTK chooses it, and the AppRun script does not touch " + c("GSK_RENDERER") + ". Only the development scripts set it (" + c("strumenti/app-sul-tablet.sh") + " defaults to " + c("vulkan") + " and sets " + c("GDK_DEBUG=offload") + "; " + c("strumenti/foto-demo.sh") + " uses " + c("cairo") + ").")

PATHS = table(["Path", "Decoder", "Export form", "Copies per frame", "Who draws"], [
    ["VA-API (first choice)", "GPU, VA-API", c("PH_ESPORTA_DMABUF"), "none: DMA-BUF handed to GTK", "GTK's renderer, chosen by GTK (on the GPU with the GL or Vulkan renderer); what GTK does internally, YUV conversion included, is not controlled by YASDE"],
    ["VA-API, mapping refused", "GPU, VA-API", c("PH_ESPORTA_RIPIEGO"), "1 download, 1 CPU conversion, then GTK's upload", "GTK's renderer, chosen by GTK, with a memory texture"],
    ["Vulkan Video (only if offered as shipped and VA-API did not open)", "GPU, Vulkan", c("PH_ESPORTA_RIPIEGO"), "1 download, 1 CPU conversion, then GTK's upload", "GTK's renderer, chosen by GTK, with a memory texture"],
    ["Software (nothing else opened)", "CPU, libavcodec", c("PH_ESPORTA_MEMORIA"), "1 CPU conversion, then GTK's upload", "GTK's renderer, chosen by GTK, with a memory texture"],
    ["Software after a DMA-BUF refusal", "CPU, libavcodec", c("PH_ESPORTA_MEMORIA"), "1 CPU conversion, then GTK's upload", "GTK's renderer, chosen by GTK, with a memory texture"],
], "«TAB» — Path, decoder, export form, copies, who draws")

S8 = S8 + PATHS + \
    p("The “then GTK's upload” part is GTK's own work with a memory texture and is not visible in the code of YASDE; the table counts only what the code of the project does.")

S9 = p("The automatic order and the checks are in " + c("src/video/decodifica.c") + ". The order is the pure function " + c("ph_decodifica_ordine_automatico(vulkan_di_fabbrica, sequence)") + ": VA-API first; Vulkan second only if " + c("vulkan_di_fabbrica") + " is true; software always last. It is proved without a graphics card by " + c("src/video/prova/prova_ordine_via.c") + ". " + c("ph_decodifica_crea(PH_VIA_AUTOMATICA)") + " tries each in order with " + c("prova_via") + " and takes the first that opens; only the last attempt fills the error text, so the reasons why VA-API or Vulkan did not open are lost. Reason for VA-API first: it hands the frame to the shell without copies, and the Vulkan via copies it (the choice of the project's owner, “route A”).", lead=True) + \
    p("<b>What " + c("ph_decodifica_vulkan_di_fabbrica") + " looks at.</b> It creates a Vulkan instance (API 1.3, no layers, no extensions), lists the physical devices, skips every device of type CPU, and returns true if any other device lists the extension " + c("VK_KHR_video_decode_h264") + ". It reads no environment variable, so a function the driver keeps switched off does not count. It does not look at queue families or video capabilities. If the instance cannot be created it returns false. It runs every time an automatic decoder is created.") + \
    p("<b>What makes a hardware via fail to open.</b> Only two checks exist: " + c("av_hwdevice_ctx_create") + " returning an error (the error text reads “via vaapi: accelerazione non disponibile: <FFmpeg message>”) and " + c("avcodec_open2") + " returning an error. Why FFmpeg refuses (no render device, no driver, a library not found) is not distinguished by the code, and the text of those errors is lost; the program reports only the outcome (" + rif("When hardware decoding is not available") + ").") + \
    p("<b>The one thing the code does not turn into a failure.</b> The hardware format is accepted only if FFmpeg offers it in " + c("get_format") + ". If the device opened but the GPU cannot decode this stream (for example an unsupported profile), the callback sets " + c("ripiego_software") + " and lets FFmpeg take its default, which is its own software decoding. This is the third case below.") + \
    p("<b>Device lost in mid-session.</b> There is no code for it. FFmpeg errors come back from " + c("ph_decodifica_dai") + " or " + c("ph_decodifica_prendi") + " as -1; the reader asks for a key frame at most every 500 ms and nothing else happens: the decoder object is replaced only when the stream is reopened (new session after a drop), when GTK refuses the DMA-BUF, or when a hardware decoder drops to software at its first packet or after a new configuration, which also recreates the decoder (" + rif("When hardware decoding is not available") + "); a device lost later is none of these. What the picture does then depends on FFmpeg and the driver and has not been tried.") + \
    p("<b>Going back to hardware.</b> A new decoder repeats the whole automatic order, hardware attempts included, so hardware is tried again whenever a stream is opened or reopened after a drop, never in the middle of a stream.")

S10 = p("What the user sees: in all three cases a decision line is written on standard error and, at most once per link session, a toast appears on screen (" + rif("Checking which path is in use") + "). All three go through " + c("via_verifica") + " (" + c("src/shell/ossatura/sv_flussi.c") + "), which asks " + c("ph_decodifica_via") + " for the via the decoder REALLY uses (" + c("ph_via_reale") + ": the chosen via, or software if FFmpeg dropped to software) after the decoder is created and after every packet given to it. It writes one line per stream and per change of via. When the via is software the cause in the line comes from three facts, tested in this order: the stream's memory preference is set and the decoder is the software one (" + c("memoria") + " and " + c("dec_software") + ") means GTK refused the DMA-BUF; else a decoder that was born with a hardware via (" + c("dec_nato_hw") + ") means the hardware via cannot sustain the stream; else no hardware via was available.", lead=True) + \
    p("<b>The toast.</b> When the via becomes software, " + c("via_verifica") + " calls " + c("ph_servizi_pubblica_decodifica_software") + " (any thread), which delivers " + c("PH_SRV_EV_DECODIFICA") + " on the GTK thread; " + c("src/shell/sistema/sistema.c") + " shows it with " + c("ph_sistema_toast_info_lungo") + ", title " + c("Decodifica video hardware non disponibile") + " (“Hardware video decoding unavailable”) and body " + c("Il video usa il processore: le app sono meno fluide. Installa i driver video VA-API o Vulkan.") + " (“Video uses the CPU: apps are less smooth. Install VA-API or Vulkan video drivers.”). It stays 9 s (" + c("DURATA_INFO_LUNGO_MS") + " in " + c("toast.c") + "); the other information toasts stay 3.2 s, notification toasts 5.2 s. It is sent at most ONCE per link session (" + c("sv->decod_sw_sess") + " holds the last session that got it): not per frame, not per window, not at every re-creation of the decoder, and if a stream goes back to hardware and falls again in the same session it is not repeated. A new session after a drop can show it again. Proved by " + c("src/shell/ossatura/prova_decodifica_avviso.c") + "; a screenshot is " + c("docs/sources/img/decoding-warning.png") + ".") + \
    h4("Case 1: no hardware via opens") + \
    ul([
        "<b>Trigger.</b> In the automatic order VA-API and, if offered, Vulkan both fail the two checks above (missing decoding drivers, a virtual machine, a card with neither VA-API nor Vulkan Video, or a missing device).",
        "<b>Steps.</b> " + c("ph_decodifica_crea") + " reaches the software via, " + c("prova_via") + " opens the " + c("h264") + " decoder with slice threads and an automatic thread count, and the decoder is created normally. Right after, " + c("via_verifica") + " sees software with no via logged yet for the stream.",
        "<b>Log.</b> " + c("[decisione] hh:mm:ss.mmm decodifica col processore - causa: nessuna via hardware disponibile: prestazioni ridotte") + " (“decoding with the processor - cause: no hardware via available: reduced performance”): the decoder was not born with a hardware via and GTK has refused nothing. The toast follows. The failed hardware attempts themselves write nothing (only the last attempt fills the error text). Only if even the software decoder cannot be created: " + c("decodifica non disponibile - il decodificatore non si e' creato") + " (“decoding not available - the decoder was not created”), once per change of state, and on recovery " + c("decodifica di nuovo disponibile - il decodificatore si e' creato") + " (“decoding available again”).",
        "<b>Cost.</b> The H.264 decoding is done by the CPU, then each frame goes through a YUV to BGRA conversion on the CPU (" + c("PH_ESPORTA_MEMORIA") + ") and GTK's upload. No figure for software decoding is recorded anywhere in the project: not measured. The tool " + c("misura_decodifica") + " can measure it on a given machine.",
        "<b>Back to hardware.</b> At the next decoder creation (stream opened or reopened), when the automatic order runs again; if hardware opens then, the line " + c("decodifica video - causa: via vaapi (scheda grafica)") + " is written (the via changed).",
    ]) + \
    h4("Case 2: the GPU decodes but GTK refuses the DMA-BUF") + \
    ul([
        "<b>Trigger.</b> The surface cannot build a DMA-BUF texture: " + c("gdk_dmabuf_texture_builder_build") + " returns NULL for a frame of DMA-BUF form (the error is discarded).",
        "<b>Steps.</b> (1) That frame is dropped and counted in the statistics as discarded and as a DMA-BUF refusal. (2) " + c("ph_srv_flusso_preferisci_memoria") + " reaches " + c("sv_flusso_memoria") + ", which sets the atomic flag " + c("memoria") + " of that stream; it is called on every refusal, not once. (3) At the next read " + c("leggi_uno") + " sees the flag with " + c("dec_software") + " still false and calls " + c("decodificatore_nuovo(sv, sf, vf, true)") + ": this is where the " + c("software") + " parameter comes from. It is not a preference, a command-line option or an environment variable: it is the flag of the stream, set only by a refusal of GTK. (4) The old decoder is freed, a software decoder is created, the stored configuration is given to it, a key frame is requested from the phone with " + c("ph_video_chiave") + ", and " + c("via_verifica") + " runs.",
        "<b>Log.</b> From the surface, once per surface: " + c("[decisione] hh:mm:ss.mmm flusso in memoria invece che DMA-BUF - causa: GTK ha rifiutato il DMA-BUF (fourcc NV12, modificatore 0x0)") + " (“stream in memory instead of DMA-BUF - cause: GTK refused the DMA-BUF (fourcc, modifier)”; the values are those of the refused frame). From the stream, at the switch: the same first words with the cause " + c("GTK ha rifiutato il DMA-BUF: decodifica software") + " (“GTK refused the DMA-BUF: software decoding”), then " + c("decodifica col processore - causa: GTK ha rifiutato il DMA-BUF: prestazioni ridotte") + " (“decoding with the processor - cause: GTK refused the DMA-BUF: reduced performance”), and the toast. Before the first DMA-BUF the surface may also have written " + c("DMA-BUF provato comunque - causa: GTK non elenca fourcc … modificatore … tra i formati importabili") + " (“DMA-BUF tried anyway - cause: GTK does not list fourcc … modifier … among the importable formats”).",
        "<b>Cost.</b> As case 1, plus the frames lost until the key frame arrives. Not measured.",
        "<b>Back to hardware.</b> Never inside the stream: the flag is never cleared, and it survives a reopening after a drop (the new decoder is created software again). A new window is a new stream and tries the DMA-BUF again.",
    ]) + \
    h4("Case 3: FFmpeg drops to software inside the hardware decoder") + \
    ul([
        "<b>Trigger.</b> The device opened, but when the stream starts FFmpeg's " + c("get_format") + " list does not contain the via's hardware format (the GPU cannot decode this stream), so " + c("scegli_formato") + " sets " + c("ripiego_software") + " and returns FFmpeg's default format. This is found at the first packet, not at creation.",
        "<b>Steps.</b> At creation " + c("via_verifica") + " still sees the hardware via and writes " + c("decodifica video - causa: via vaapi (scheda grafica)") + "; " + c("dec_nato_hw") + " is set. " + c("ph_decodifica_dai") + " then sends the first packet; the fall-back flag turns " + c("ph_decodifica_via") + " into software (" + c("ph_via_reale") + "), and " + c("ph_decodifica_dai") + " itself returns -1 for this packet. " + c("via_verifica") + " is called right after it even when it fails: it writes the processor line, raises the toast, and, because the decoder was born hardware, recreates it ONCE as " + c("PH_VIA_SOFTWARE") + ", gives it the stored configuration, requests ONE key frame from the phone and tells " + c("leggi_uno") + " to drop the packet in hand. From then on there are no more errors at every packet and no key-frame requests every 500 ms. Frames are exported as memory frames. That this works on a GPU that cannot decode a stream is read from the code and was not run.",
        "<b>Log.</b> " + c("[decisione] hh:mm:ss.mmm decodifica col processore - causa: la via hardware non regge il flusso: prestazioni ridotte") + " (“decoding with the processor - cause: the hardware via cannot sustain the stream: reduced performance”), after the " + c("via vaapi") + " line, and the toast. No " + c("flusso in memoria invece che DMA-BUF") + " line: that one is written only when GTK really refused.",
        "<b>Cost.</b> CPU decoding as above, plus the lost time of the failed first packets and one key frame. Not measured.",
        "<b>Back to hardware.</b> At the next decoder creation, as in case 1.",
    ]) + \
    warn("Case 3 is the least certain, because no run is recorded: it depends on how a given GPU and FFmpeg behave at the first packet. All three cases write a line and raise the toast.")

S11 = p("Everything the program says about video paths goes to standard error (the terminal that started the AppImage), plus the toast described above. There is no log file.", lead=True) + \
    p("Decision lines have the form " + c("[decisione] hh:mm:ss.mmm <what> - causa: <cause>") + " (" + c("ph_shell_decisione") + ", " + c("src/shell/comune/consegna.c") + ").") + \
    table(["Line (what - cause)", "Meaning", "Where"], [
        [c("decodifica video - via vaapi (scheda grafica)") + " or " + c("via vulkan (scheda grafica)"), "“video decoding - via vaapi (graphics card)”: the via the decoder really uses, one line per stream and per change of via", c("sv_flussi.c") + ", " + c("via_verifica")],
        [c("decodifica col processore - nessuna via hardware disponibile: prestazioni ridotte"), "case 1: no hardware via opened", c("sv_flussi.c") + ", " + c("via_verifica")],
        [c("decodifica col processore - GTK ha rifiutato il DMA-BUF: prestazioni ridotte"), "case 2", c("sv_flussi.c") + ", " + c("via_verifica")],
        [c("decodifica col processore - la via hardware non regge il flusso: prestazioni ridotte"), "case 3", c("sv_flussi.c") + ", " + c("via_verifica")],
        [c("flusso in memoria invece che DMA-BUF - fotogramma della scheda grafica non mappabile, copiato in memoria"), "“stream in memory instead of DMA-BUF - GPU frame that cannot be mapped, copied to memory”: " + c("PH_ESPORTA_RIPIEGO") + ", that is the Vulkan via, or VA-API with a refused mapping; once per stream", c("sv_flussi.c") + ", " + c("esporta")],
        [c("flusso in memoria invece che DMA-BUF - GTK ha rifiutato il DMA-BUF (fourcc %s, modificatore 0x%llx)"), "GTK refused a DMA-BUF texture; once per surface", c("superficie.c") + ", " + c("mostra")],
        [c("flusso in memoria invece che DMA-BUF - GTK ha rifiutato il DMA-BUF: decodifica software"), "the stream switched to the software decoder (case 2)", c("sv_flussi.c") + ", " + c("decodificatore_nuovo")],
        [c("DMA-BUF provato comunque - GTK non elenca fourcc %s modificatore 0x%llx tra i formati importabili"), "“DMA-BUF tried anyway”; may precede a refusal", c("superficie.c") + ", " + c("texture_da")],
        [c("spazio dei colori lasciato a GTK - GTK non ha costruito lo spazio dei colori %d: %s"), "“colour space left to GTK”: the colour state could not be built", c("superficie.c") + ", " + c("stato_colore")],
        [c("fotogramma scartato - esportazione non riuscita"), "“frame discarded - export failed”, once; then " + c("fotogrammi scartati - %u in tutto prima di questo") + " when exports work again", c("sv_flussi.c") + ", " + c("esporta")],
        [c("decodifica non disponibile - il decodificatore non si e' creato"), "no decoder at all, not even software", c("sv_flussi.c") + ", " + c("decodificatore_nuovo")],
    ], "«TAB» — Decision lines about the video path") + \
    p("<b>Statistics.</b> With the environment variable " + c("PH_SUPERFICIE_STAT=1") + " (a value starting with “1”, read when each surface is created) every surface writes every 5 s, from its reading thread: " + c("superficie N: ricevuti X (R/s), mostrati Y (R/s), scartati Z, rifiuti DMA-BUF W") + " (“surface N: received, shown, discarded, DMA-BUF refusals”; N counts surfaces from 1 in creation order). Received and shown are the frames read and the textures put on screen with their rates since the last line; refusals above 0 mean GTK is refusing the DMA-BUF (" + c("src/shell/superficie/superficie.c") + ").") + \
    p("<b>What the lines tell.</b> The first line of a stream names the via really in use: " + c("vaapi") + " means the copy-free path unless a " + c("flusso in memoria invece che DMA-BUF") + " line follows (mapping refused, or GTK refused); " + c("vulkan") + " always means the copying path (" + c("PH_ESPORTA_RIPIEGO") + "). The “processor” lines say the decoding is software and why. Because the line is written when the decoder is created and after each packet, a fall-back found at the first packet or after a new configuration (case 3) shows as a " + c("vaapi") + " line followed by a processor line.") + \
    p("<b>Which via a machine gets.</b> The program itself now says it, in the first decision line of each stream. The measuring tools also print it, because they call " + c("ph_decodifica_via") + ": " + c("finestra-prova") + " and " + c("prototipo-gtk") + " write " + c("decodifica: via vaapi") + " (or vulkan, software) on standard error; " + c("misura-flussi") + " prints the via of each stream; " + c("misura_decodifica") + " prints it with the pixel format and the decoding time. With " + c("--via automatica") + " (the default) they use the same order as the program. GTK's own offload messages are available with " + c("GDK_DEBUG=offload") + ", which the development scripts set.") + \
    p("<b>Forcing a path.</b> The program has no switch for it: no preference, option or variable chooses the decoding via, and the order cannot be changed. The option exists only in the tools, as " + c("--via automatica|vaapi|vulkan|software") + " (" + c("misura-flussi") + " also accepts " + c("nessuna") + "; " + c("misura_decodifica") + " takes the via as its second argument), and an explicit via fails if it is not available. The project plan speaks of a switch for measuring the two vias: it is this one, in the tools.") + \
    table(["Tool", "What it measures"], [
        [c("strumenti/misura-flussi.c"), "opens one session per app on a real phone and measures, for each stream, the frames that arrive, the bandwidth, their regularity (intervals), and with decoding the via, the decoding errors and the mean decoding time; answers how many encoders in parallel the phone supports"],
        [c("strumenti/prototipo-gtk.c"), "a GTK4 prototype, not the shell: composes several streams in windows, with the no-copy DMA-BUF path by default and " + c("--copia") + " for the memory path; " + c("--giostra") + " moves and resizes the windows by itself. It measured whether GTK composes several streams without copies and without stutter"],
        [c("src/video/misura_decodifica.c"), "decodes a raw H.264 file with the chosen via and prints frames, size, pixel format, mean and worst decoding time and frames per second"],
        [c("strumenti/finestra-prova.c"), "a bare window (SDL3) that copies frames from the GPU to memory and measures click-to-image latency; not the final path"],
    ], "«TAB» — Measuring tools")

S12 = p("<b>Libraries from the system.</b> The AppImage includes a minimal FFmpeg (" + c("pacchetto/dentro.sh") + ": decoder " + c("h264") + ", parser, PNG encoder, MP4 muxer, " + c("--enable-hwaccel=h264_vaapi") + " and " + c("--enable-hwaccel=h264_vulkan") + ", with libva, libdrm and Vulkan), but the following stay with the system and are required: " + c("libva.so.2") + " and " + c("libva-drm.so.2") + " (without them the program does not start: they are needed by FFmpeg), " + c("libvulkan.so.1") + " (the loader: without it the program does not start) and " + c("libdrm.so.2") + ". For hardware decoding the machine also needs a VA-API driver for the GPU (Vulkan Video: a Vulkan driver that offers " + c("VK_KHR_video_decode_h264") + "). Source: " + c("pacchetto/LEGGIMI.md") + " and the file " + c("SYSTEM-REQUIREMENTS.txt") + " that the build writes.", lead=True) + \
    p("<b>What was measured, and where.</b> From the project plan: on one machine with an Intel GPU (GTK 4.18.6), where Vulkan decoding is switched off by the driver as shipped, GTK4 drawing through Vulkan with the images passed from the decoder without copying gave 59 frames per second with 3 windows and regular intervals; the default renderer (GL) gave 54 even with 5 windows; with the images copied, 27 frames per second with 3 windows. Those are measurements of the prototype " + c("strumenti/prototipo-gtk.c") + " on recorded video, not of the final program. Not yet measured: five really active apps from a real phone, and HiDPI. The same machine is where the choice of route A was made (VA-API where Vulkan Video is off).") + \
    p("<b>Direct hand-off to the screen (offload).</b> On that machine GTK never printed “Attaching … GdkDmabufTexture” with " + c("GDK_DEBUG=offload") + ", even with forced offload and with both renderers, not in the surface demo and not in the prototype: the direct hand-off is not active. The textures are DMA-BUF (no refusals), so the video reaches the GPU without a copy in memory and only the last step is missing. Rounded corners and clipping of the real windows would prevent it anyway. Open point.") + \
    p("<b>What was run, and what was not.</b> The program has run live with video (1440p, two screens, a test of 23 Nov 2026, recorded in the project plan), but which decoding via it used was not recorded then. Not proved on real hardware: the Vulkan via, and the three software cases; the software cases also have no recorded measurement.") + \
    p("<b>Known limit.</b> With only Vulkan (VA-API absent) every frame is copied to memory (" + c("PH_ESPORTA_RIPIEGO") + "): the copy-free path exists only with VA-API. The automatic order puts VA-API first for that reason.") + \
    note("The surface also reduces the rate of a stream the GTK thread cannot follow, and logs it (" + c("frequenza fotogrammi ridotta") + "); that is a separate mechanism, described with the surface.")


